import{_ as t,o as a,c as d,a0 as o}from"./chunks/framework.CNXp-E7Q.js";const l=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/architecture.md","filePath":"explanation/architecture.md"}'),r={name:"explanation/architecture.md"};function s(n,e,c,i,p,h){return a(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><blockquote><p><strong>Binary surface (ADR-0006 amendment).</strong> bupha&#39;s shipped surface is the engine library plus <code>tamias-driver-bupha</code> — tamias bundles (<code>type: bupha</code>) deploy provider units that exec the driver&#39;s <code>host</code> verb, which runs the watcher engine (<code>bupha-watch</code>) in-process. The <code>bupha</code> CLI binary is a dev/debug harness (<code>run</code>/<code>doctor</code>/<code>import</code>/<code>watch</code>); production webhook ingress is a peregrin campaign (ADR-0007), with the bupha webhook listener as the standalone/dev fallback.</p></blockquote><p>bupha is a port/adapter monorepo: every external concern sits behind a trait (a <em>port</em>), and each integration is a crate that implements it (an <em>impl</em>). <code>bupha-core</code> is the pure domain — config shape, queue semantics, shared primitives — and depends on nothing outside itself; <code>bupha-cli</code> is the engine lib + clap tree (<code>command()</code>/<code>run_from</code>) the dev harness and the driver&#39;s <code>cli</code>/ <code>ops</code> surfaces share (the deployed composition is <code>tamias-driver-bupha</code> + tamias provider units).</p><h2 id="crate-map" tabindex="-1">Crate map <a class="header-anchor" href="#crate-map" aria-label="Permalink to &quot;Crate map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>crate</th><th>layer</th><th>purpose</th></tr></thead><tbody><tr><td><code>bupha-core</code></td><td>domain</td><td>bupha domain core: config types, job queues, shared primitives — no ports, no integrations</td></tr><tr><td><code>bupha-access</code></td><td>port</td><td>Access port: who may trigger a repo</td></tr><tr><td><code>bupha-attest</code></td><td>port</td><td>Attest port: signed run provenance (SLSA-style predicate)</td></tr><tr><td><code>bupha-cache</code></td><td>port</td><td>Cache port: artifact-cache backend for runners</td></tr><tr><td><code>bupha-queue</code></td><td>port</td><td>QueueStore port: queue persistence</td></tr><tr><td><code>bupha-runner</code></td><td>port</td><td>Runner port: how a job becomes a spawned process</td></tr><tr><td><code>bupha-status</code></td><td>port</td><td>StatusSink port: where run outcomes are reported</td></tr><tr><td><code>bupha-telemetry</code></td><td>port</td><td>Telemetry port: fire-and-forget pipeline events</td></tr><tr><td><code>bupha-trigger</code></td><td>port</td><td>Source port: where pushes come from — forge webhooks, WAL polls, …</td></tr><tr><td><code>bupha-access-file</code></td><td>adapter</td><td>Access adapter: allowlist of forge logins from config</td></tr><tr><td><code>bupha-access-forge</code></td><td>adapter</td><td>Access adapter: forge collaborator-permission check</td></tr><tr><td><code>bupha-attest-file</code></td><td>adapter</td><td>Attest adapter: SLSA-shape predicate JSON per run (unsigned v1)</td></tr><tr><td><code>bupha-attest-sigstore</code></td><td>adapter</td><td>Attest adapter: cosign-signed run predicates (needs cosign + key)</td></tr><tr><td><code>bupha-audit-file</code></td><td>adapter</td><td>Audit adapter: append access/outcome decisions to a JSONL file</td></tr><tr><td><code>bupha-cache-sccache</code></td><td>adapter</td><td>Cache impl: sccache-compatible conf (file/S3/R2/GCS via conf)</td></tr><tr><td><code>bupha-config-file</code></td><td>adapter</td><td>File impl of the config port — scarab-config discovery (explicit → $BUPHA_CONFIG → ./bupha.* → ~/.config/bupha/) + local TOML/YAML format dispatch for bupha_core::Config</td></tr><tr><td><code>bupha-container</code></td><td>adapter</td><td>Runner adapter: unprivileged container (podman/docker), network-off</td></tr><tr><td><code>bupha-dagger</code></td><td>adapter</td><td>Runner impl: <code>dagger call &amp;lt;fn&amp;gt;</code> per job</td></tr><tr><td><code>bupha-driver</code></td><td>adapter</td><td>tamias-driver-bupha — pavo view driver over bupha&#39;s on-disk run/queue state (read-only)</td></tr><tr><td><code>bupha-gha</code></td><td>adapter</td><td>Runner impl: .github/workflows/*.yml executed natively — GitHub Actions as CI dialect</td></tr><tr><td><code>bupha-gha-runner</code></td><td>adapter</td><td>GitHub Actions self-hosted runner — speaks the actions/runner broker protocol so repos can runs-on: [self-hosted, bupha]</td></tr><tr><td><code>bupha-github</code></td><td>adapter</td><td>GitHub impl: push-webhook trigger + commit-status sink</td></tr><tr><td><code>bupha-history</code></td><td>adapter</td><td>Run-history adapter: JSONL records per finished run</td></tr><tr><td><code>bupha-http</code></td><td>adapter</td><td>Runner impl: remote execution via HTTP agent (tar worktree + poll)</td></tr><tr><td><code>bupha-plane</code></td><td>adapter</td><td>ci-job entity plane — hypha EntityPlane impl for the bupha↔hypha/peregrin seam (P-002)</td></tr><tr><td><code>bupha-secret-cuora</code></td><td>adapter</td><td>Secret impl: cuora broker via the cuora CLI (canonical secrets story, T-056)</td></tr><tr><td><code>bupha-shell</code></td><td>adapter</td><td>Runner impl: bash -c &lt;cmd&gt; per job — no containers</td></tr><tr><td><code>bupha-ssh</code></td><td>adapter</td><td>Runner impl: remote execution over ssh (rsync worktree + run)</td></tr><tr><td><code>bupha-sturn</code></td><td>adapter</td><td>sturn source impl: reads refs/sturn/* WAL state out of a clone via git plumbing</td></tr><tr><td><code>bupha-telemetry-otel</code></td><td>adapter</td><td>Telemetry adapter: OpenMetrics textfile for Prometheus</td></tr><tr><td><code>bupha-watch</code></td><td>adapter</td><td>bupha watcher engine host — trigger → queue → runner → status pipeline shared by <code>bupha watch</code> and <code>tamias-driver-bupha host</code></td></tr><tr><td><code>bupha</code></td><td>binary</td><td>bupha — queue engine for event-driven jobs: shipped as CI</td></tr></tbody></table><p><code>modules/dagger/</code> (Python SDK) is the shared pipeline module the dev CLI&#39;s <code>bupha init</code> installs into consumer repos — pinned to a sha.</p><h2 id="sources-—-the-ingest-edge" tabindex="-1">Sources — the ingest edge <a class="header-anchor" href="#sources-—-the-ingest-edge" aria-label="Permalink to &quot;Sources — the ingest edge&quot;">​</a></h2><p>bupha is a queue engine: <code>source → queue → effect</code>. Everything in front of the queue is a <code>Source</code> — a long-running ingest that emits normalized <code>(repo, ref, sha, sender)</code> pushes; everything behind it (queues, runner, status sinks) is source-agnostic. A watcher process — <code>tamias-driver-bupha host</code> in deployed units, <code>bupha watch</code> in the dev harness — runs every configured source and feeds one shared ingest path.</p><table tabindex="0"><thead><tr><th>source</th><th>config</th><th>emits on</th></tr></thead><tbody><tr><td><code>github-webhook</code></td><td><code>trigger.kind = &quot;github&quot;</code> (+ <code>[trigger]</code> listener, secrets, tunnel)</td><td>verified <code>push</code>/<code>pull_request</code> deliveries (<code>[[repo]] events</code>)</td></tr><tr><td><code>sturn-wal</code></td><td><code>[trigger.sturn]</code> + <code>[[repo]] sturn = true</code></td><td><code>Op::Snapshot</code> WAL events</td></tr></tbody></table><p><code>pull_request</code> deliveries are opt-in per repo (<code>events</code>): the PR head sha runs in a worktree while <code>branch</code>/job filters evaluate the <em>base</em> ref — a <code>refs/heads/main</code> gate covers PRs targeting main with no extra config.</p><p><code>Trigger</code> is the narrower per-request port a webhook <code>Source</code> drives — is this our event, which repo (untrusted hint), does the signature verify, what does the payload ask for. New forges mean a new <code>Trigger</code> impl reusing the same webhook listener; new <em>kinds</em> of ingest (gitlab webhook, cron, poll-ref, file-watch) are new <code>Source</code> impls — neither touches the queue.</p><h2 id="webhook-request-flow" tabindex="-1">Webhook request flow <a class="header-anchor" href="#webhook-request-flow" aria-label="Permalink to &quot;Webhook request flow&quot;">​</a></h2><p>The <code>github-webhook</code> source&#39;s per-request pipeline (byte-stable — routing and statuses are part of the contract):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /hook</span></span>
<span class="line"><span>  → 1. path check (404 otherwise)</span></span>
<span class="line"><span>  → 2. read body (≤ 2 MiB)</span></span>
<span class="line"><span>  → 3. repo hint — untrusted peek at repository.full_name,</span></span>
<span class="line"><span>       selects the watched [[repo]] and its secret; an</span></span>
<span class="line"><span>       unwatched repo 404s (it can never verify)</span></span>
<span class="line"><span>  → 4. signature verify (Trigger port — github impl: HMAC</span></span>
<span class="line"><span>       sha256, constant-time; key = repo&#39;s secret_env,</span></span>
<span class="line"><span>       falling back to trigger.secret_env)</span></span>
<span class="line"><span>  → 5. dedup delivery id (bounded 10k ring; github impl uses</span></span>
<span class="line"><span>       X-GitHub-Delivery)</span></span>
<span class="line"><span>  → 6. parse — skip deletes/zero-sha; revision must be path-safe</span></span>
<span class="line"><span>  → 7. route — git_ref selects every job of the repo watching it</span></span>
<span class="line"><span>       ([[repo.jobs]] entries, or the repo&#39;s implicit pipeline);</span></span>
<span class="line"><span>       forge-attested sender checked against the access policy</span></span>
<span class="line"><span>  → 8. enqueue — one queue per job; a push fan-outs into every</span></span>
<span class="line"><span>       matched queue; jobs this box&#39;s \`[worker] labels\` can&#39;t</span></span>
<span class="line"><span>       satisfy belong to the ci-job entity plane instead; persist</span></span>
<span class="line"><span>       via QueueStore (dev \`json\` file)</span></span>
<span class="line"><span>  → 9. one global worker — Vcs fetch, detached worktree</span></span>
<span class="line"><span>       at &lt;base&gt;-&lt;repo&gt;[-&lt;job&gt;]-&lt;sha12&gt;</span></span>
<span class="line"><span>  → 10. spawn run handle (token via env:// name, never argv)</span></span>
<span class="line"><span>  → 11. status — pending → success/error; superseded and</span></span>
<span class="line"><span>        cancelled shas get honest error statuses. Runners may</span></span>
<span class="line"><span>        report sub-job verdicts (\`Runner::status_reports\`) —</span></span>
<span class="line"><span>        the gha dialect emits one per expanded workflow job /</span></span>
<span class="line"><span>        matrix leg, posted under \`&lt;context&gt;/&lt;workflow&gt;/&lt;job&gt;\`</span></span>
<span class="line"><span>        via \`StatusSink::post_ctx\` before the aggregate lands</span></span></code></pre></div><h2 id="queue-semantics" tabindex="-1">Queue semantics <a class="header-anchor" href="#queue-semantics" aria-label="Permalink to &quot;Queue semantics&quot;">​</a></h2><p>Queues are per <em>job</em>: a <code>[[repo]]</code> is one implicit pipeline unless it declares <code>[[repo.jobs]]</code>, in which case each job gets an independent queue (<code>name:job</code> keys), branch filter, runner and status context. One push fan-outs into every job queue whose <code>branch</code> matches the ref — same-repo jobs are independent of each other (latest-wins on one never touches another&#39;s pending slot, and <code>cancel_running</code> only kills its own job&#39;s in-flight run).</p><table tabindex="0"><thead><tr><th>policy</th><th>pending</th><th>on new push</th><th>use for</th></tr></thead><tbody><tr><td><code>latest</code> (default)</td><td>1 sha</td><td>supersedes pending; <code>cancel_running</code> may kill in-flight</td><td>CI gates</td></tr><tr><td><code>all</code></td><td>bounded FIFO (32)</td><td>appends; oldest evicted past cap; <code>cancel_running</code> rejected at load — it would drop a promised commit</td><td>releases</td></tr></tbody></table><p>Persistence: accepted work writes through the <code>QueueStore</code> port (the dev <code>json</code> file under <code>worktree.base</code>; the durable path is the ci-job entity plane — see <a href="./../how-to/distributed-runners.html">distributed runners</a>) and on restart the interrupted <code>running</code> sha is re-queued at the front.</p><p>One <strong>global worker</strong> serializes runs across all repos — a second push queues behind the in-flight job. Deliberate (one box, bounded resource use), not a hang: <code>journalctl --user -u bupha-watch</code> shows the queue moving.</p><h2 id="security-model" tabindex="-1">Security model <a class="header-anchor" href="#security-model" aria-label="Permalink to &quot;Security model&quot;">​</a></h2><ul><li>mandatory HMAC (constant-time compare) — unauthenticated payloads never reach the queue</li><li>per-repo webhook secrets (<code>[[repo]] secret_env</code>, falling back to <code>trigger.secret_env</code>) — the repo is resolved before verify, so a hook admin on one repo can&#39;t forge signed pushes for another</li><li>body cap, delivery-id replay dedup, hex-sha validation before the value touches paths or status URLs</li><li>webhook takeover is exact-URL only; hook API calls are timed out</li><li>config names secrets (<code>secret_env</code>/<code>token_env</code>) — values resolve env → cuora (<code>cuora://bupha/&lt;NAME&gt;</code>, canonical, T-056; fleet secrets migrated, T-059) → <code>~/.config/bupha/env</code> (0600 — dev-mode / no-cuora fallback; keyring leg dropped post-T-077); the runner gets the token through its own mechanism (<code>env://</code> for dagger)</li></ul><h2 id="extending" tabindex="-1">Extending <a class="header-anchor" href="#extending" aria-label="Permalink to &quot;Extending&quot;">​</a></h2><table tabindex="0"><thead><tr><th>to add…</th><th>write…</th><th>core changes?</th></tr></thead><tbody><tr><td>push source (cron, poll)</td><td><code>Source</code> adapter crate</td><td>no</td></tr><tr><td>forge (gitea/gitlab)</td><td><code>Trigger</code> + <code>StatusSink</code> adapter crate</td><td>no</td></tr><tr><td>pipeline backend</td><td><code>Runner</code> adapter crate</td><td>no</td></tr><tr><td>ingress (fly/tailscale)</td><td><code>Tunnel</code> adapter crate</td><td>no</td></tr></tbody></table>`,23)])])}const b=t(r,[["render",s]]);export{l as __pageData,b as default};
